import "@/components/audio-ui/piano/web";

const MIN_PITCH = 48;
const MAX_PITCH = 72;

/** Draws the keyboard into `element`, and returns what takes it away. */
export function pianoWebDemo(element) {
  const keys = Array.from(
    { length: MAX_PITCH - MIN_PITCH + 1 },
    (_, index) =>
      `<audio-ui-piano-key pitch="${MIN_PITCH + index}"><button class="top-0 outline-none transition-colors duration-100 ease-out focus-visible:z-20 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset data-[color=white]:z-0 data-[color=white]:h-full data-[color=white]:border-[color:color-mix(in_oklab,var(--piano-key-black)_30%,transparent)] data-[color=white]:border-x data-[color=white]:bg-(--piano-key-white) data-[color=black]:z-10 data-[color=black]:h-[60%] data-[color=black]:rounded-none data-[color=black]:bg-(--piano-key-black) data-[selected]:data-[color]:bg-primary motion-reduce:transition-none cursor-pointer"></button></audio-ui-piano-key>`
  ).join("");
  element.innerHTML = `
    <audio-ui-piano aria-label="Piano" class="rounded-none border border-transparent bg-card ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-1 hover:ring-ring/50 has-[:focus-visible]:ring-1 has-[:focus-visible]:ring-ring/50 active:ring-1 active:ring-ring/50 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none [--piano-key-white:oklch(0.985_0_0)] [--piano-key-black:oklch(0.205_0_0)] h-32 w-full touch-none select-none overflow-hidden data-disabled:pointer-events-none data-disabled:opacity-50" min-pitch="${MIN_PITCH}" max-pitch="${MAX_PITCH}">${keys}</audio-ui-piano>`;
  return () => {
    element.innerHTML = "";
  };
}
